// input = { txId, outputIndex, publicKey, signature }
for (const input of tx.inputs) {
	const spent = utxo.get(`${input.txId}:${input.outputIndex}`);
	if (spent === undefined) return false;
	if (!verify(input.publicKey, tx.id, input.signature)) return false;
}
return true;

