const spent = utxo.get(`${input.txId}:${input.outputIndex}`);
if (spent === undefined) return false;
// A chave vem da saída gasta, não de quem gasta. / The key comes from the spent output, not from the spender.
if (!verify(spent.publicKey, tx.id, input.signature)) return false;

